-- Rollback for iso-5667-10-md-verification-pack.sql (VA pass, 2026-09-08).
-- Reverts ONLY the rows that pack touched (identified by the verification_note tag it writes) and ONLY for
-- standard ISO-5667-10 (joined through worksheet_templates -> standards.code). The 2026-09-08 export showed
-- ALL 81 fields and ALL 3 equations at verification_status='imported_unverified', so every row returns to
-- exactly that status. Nothing else on the standard is touched: no gate, no enum, no is_required, no severity.
-- NO transaction control statements in this file by design (the runner supplies the transaction).

-- ---- Section A: fields (81 rows) - prior status = imported_unverified ----
update public.fields f set verification_status='imported_unverified', verification_quote=null, verification_note=null, verified_at=null
  from public.worksheet_templates wt join public.standards s on s.id = wt.standard_id
 where wt.id = f.worksheet_template_id and s.code = 'ISO-5667-10'
   and f.id in ('c8f5803c-e1ce-4f0b-bf66-480f70529f8d','c042a098-6e00-4d17-ae16-a32849dd9d38','cecafc04-1e18-41cc-9a8f-86467866d52b','8b6a91d8-6997-433b-b589-23b05cf92dc0','39b44650-00fa-42df-a245-9e19ccb45764','2e278d03-455d-4a86-9dd0-9644477adc95','6e7d18b4-d666-44f4-bc85-9b7d5b98adeb','57ee5fca-c952-4bb7-a8a4-962b044af865','c07c5ce1-a50e-4b40-9df6-d6ec12d114e0','529b1b8f-aaa4-4282-a678-def69d27872b','1cbfd0bc-6e8d-45ac-bb9c-f114f8099a35','c356da2d-e5e5-4cc4-a744-8d701672d70a','34c0783d-7efa-4123-b0b6-28cdabf81f66','81b2ebee-c445-4ebf-858d-087bfb1006bd','ae8b2a13-fc2b-4ef1-b316-d721c2f88e04','f4028c97-8527-4674-934c-5792cd888e4f','6ea44d1b-7bed-4682-bfd5-bf0b8e0cbb8c','15bec5b5-6d92-4c34-9634-47cfbdc8c63f','1a2b5f2f-2059-44e6-ad6d-985b8a6c5f79','acad4ff6-d945-4473-917b-66f3756d281e','53abf550-308b-4fd6-a6d7-b3617161a497','d698fb24-6e53-4517-9ccf-fd9b765657b3','25903275-6b6b-4411-860c-85e42730ae6a','20df9ea4-d27f-4720-b69c-bd8e97a47296','7037b6cf-d14b-46e9-b7fa-dbcd2bc5e8dc','876dd118-68e3-4fad-9a02-fc8fba6e6c54','6eea4ca2-6b19-45db-adfd-46cebd980032','29c432a1-2779-4af3-bb0d-e9df9308d82c','2e2d8ad8-40e0-4f3d-8458-9caa631f29ed','83bac5d9-24ca-4e60-97b4-4daa544c19e3','b5259a50-53a1-44f9-b6d2-c50c4b1ef02d','f6363e13-2cad-41e3-9972-e19681a2e0c8','519743ba-255b-4256-821b-2ac0fcd364dd','5038da73-9031-4871-851d-4b4c116f3c6f','34d21c52-af42-4aa1-be7c-8fb4adceb19f','d4dc4477-d5f5-42f3-8239-502d5c402fc4','29aac76a-aa0d-417b-bb56-e1950bdb61b1','4a744869-d3fc-49e2-84be-c51deb5e712e','42e6e9fa-2168-4bf0-bf11-f86b8c60a981','118db3e9-9f00-4334-a9bd-99cad2078986','05123520-8930-472a-9c94-d7537098fe06','0eeb9516-26b9-455e-bca1-042ef5c35bdd','84d78b64-ae97-427c-ad5b-42bca0db153a','e8c74d0c-9ccb-4948-a579-8dcf9f3ead4f','241090d7-74e7-4fff-acda-dec134365445','5c223b68-25fa-4578-822f-bd13a25ac4e4','7d8cd949-0345-42cc-ad6b-9fce86837ad5','78fa700f-61da-4e1f-838a-e3bc473376cb','9451f4b3-57bc-44d0-9ef3-0c99baa4f01e','505ae7d7-6c3d-403f-aa6a-cae1f3b2c4e9','7f149092-558e-4fda-9f80-809398a0c