-- ---- Section B: equations (3 rows) - prior status = imported_unverified ----
update public.equations e set verification_status='imported_unverified', verification_quote=null, verification_note=null, verified_at=null
  from public.worksheet_templates wt join public.standards s on s.id = wt.standard_id
 where wt.id = e.worksheet_template_id and s.code = 'ISO-5667-10'
   and e.id in ('ba1bf923-06cc-46aa-aab2-40f0dfa7ae22','c7908fa3-c685-4d8d-a7cd-57e134794a85','6a587ea8-30d9-4eb9-ad5a-b8d8fd60228d')
